const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider       = \"prisma-client-js\"\n  output         = \"../generated/prisma\"\n  driverAdapters = true\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// =========================================================\n// IDENTITY / AUTH — single table for every human who logs in\n// =========================================================\n\n/// One login system for Super Admins, Hotel Owners, Branch Managers, and Staff.\n/// Scope is determined by branch_id + role, not by which table the row lives in.\n/// Hotel-owner-specific data (hotel_id, address) lives in hotel_owners, a 1-to-1\n/// profile table — NOT a separate login system.\nmodel users {\n  id String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n\n  // --- scope ---\n  hotel_id  String? @db.Uuid\n  branch_id String? @db.Uuid // set for branch_manager + staff roles\n\n  // --- role ---\n  role_id String @db.Uuid\n\n  // --- identity / credentials (union of what any role might use) ---\n  full_name     String  @db.VarChar(150)\n  email         String? @unique @db.VarChar(150)\n  phone         String? @unique @db.VarChar(30)\n  username      String? @db.VarChar(50)\n  password_hash String?\n  pin_code      String? @db.VarChar(10) // fast POS login for waiters/cashiers\n\n  reset_token            String?   @db.VarChar(64)\n  reset_token_expires_at DateTime? @db.Timestamptz(6)\n  is_active              Boolean?  @default(true)\n  hired_at               DateTime? @db.Date // meaningful for staff, null otherwise\n\n  created_at DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at DateTime? @default(now()) @db.Timestamptz(6)\n\n  staff_salaries         staff_salaries[]\n  payslips               payslips[]             @relation(\"payslip_recipient\")\n  advances_received      staff_advances[]       @relation(\"advance_recipient\")\n  advances_approved      staff_advances[]       @relation(\"advance_approver\")\n  staff_attendance       staff_attendance[]\n  expenses_created       expenses[]             @relation(\"expense_creator\")\n  expenses_approved      expenses[]             @relation(\"expense_approver\")\n  payroll_runs_processed payroll_runs[]         @relation(\"payroll_processor\")\n  leave_requests         staff_leave_requests[] @relation(\"leave_requester\")\n  leave_approved         staff_leave_requests[] @relation(\"leave_approver\")\n\n  stays_checked_in  room_stays[] @relation(\"stay_checkin\")\n  stays_checked_out room_stays[] @relation(\"stay_checkout\")\n\n  roles    roles     @relation(fields: [role_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  branches branches? @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  hotel_owners           hotel_owners[]\n  inventory_transactions inventory_transactions[]\n  order_discounts        order_discounts[]\n  orders                 orders[]\n  payments               payments[]\n  pos_devices            pos_devices[]\n  shifts                 shifts[]\n  table_sessions         table_sessions[]\n\n  @@index([branch_id], map: \"idx_users_branch\")\n  @@index([role_id], map: \"idx_users_role\")\n}\n\nmodel roles {\n  id               String             @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name             String             @unique @db.VarChar(50) // super_admin, hotel_owner, branch_manager, waiter, cashier, kitchen, ...\n  scope            String             @default(\"branch\") @db.VarChar(20) // platform | hotel | branch\n  role_permissions role_permissions[]\n  users            users[]\n}\n\nmodel permissions {\n  id               String             @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  code             String             @unique @db.VarChar(100)\n  description      String?\n  role_permissions role_permissions[]\n}\n\nmodel role_permissions {\n  role_id       String      @db.Uuid\n  permission_id String      @db.Uuid\n  permissions   permissions @relation(fields: [permission_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  roles         roles       @relation(fields: [role_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([role_id, permission_id])\n}\n\n// =========================================================\n// BUYERS — online customers (self-signup, platform-wide)\n// =========================================================\n\n/// Online customers who order/book from the public web app.\n/// Entirely separate from `customers` (which are POS walk-ins added\n/// by staff, scoped per-hotel). A buyer logs in with email or phone\n/// and can order at ANY hotel on the platform.\nmodel buyers {\n  id                     String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  full_name              String    @db.VarChar(150)\n  email                  String?   @unique @db.VarChar(150)\n  phone                  String?   @unique @db.VarChar(30)\n  password_hash          String\n  is_active              Boolean?  @default(true)\n  reset_token            String?   @db.VarChar(64)\n  reset_token_expires_at DateTime? @db.Timestamptz(6)\n  created_at             DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at             DateTime? @default(now()) @db.Timestamptz(6)\n\n  orders     orders[]\n  reviews    reviews[]\n  room_stays room_stays[]\n  payments   payments[]\n\n  @@index([reset_token], map: \"idx_buyers_reset_token\")\n}\n\n// =========================================================\n// PLATFORM / TENANCY\n// =========================================================\n\n/// This table contains check constraints and requires additional setup for migrations.\nmodel hotels {\n  id   String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name String @db.VarChar(150)\n  slug String @unique @db.VarChar(150)\n\n  logo_url                String?\n  subscription_plan_id    String?   @db.Uuid\n  subscription_status     String?   @default(\"trial\")\n  subscription_expires_at DateTime? @db.Timestamptz(6)\n  is_online               Boolean   @default(false)\n  business_type           String    @default(\"hotel\") @db.VarChar(30)\n  delivery_type           String    @default(\"none\") @db.VarChar(20) // ← must be here\n  created_at              DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at              DateTime? @default(now()) @db.Timestamptz(6)\n\n  subscription_plans  subscription_plans?  @relation(fields: [subscription_plan_id], references: [id])\n  verification_status String               @default(\"pending\") @db.VarChar(20)\n  // the single owner profile for this hotel (1-to-1)\n  hotel_owner         hotel_owners?\n  expense_categories  expense_categories[]\n  menu_categories     menu_categories[]\n  menu_items          menu_items[]\n\n  branches   branches[]\n  customers  customers[]\n  audit_logs audit_logs[]\n}\n\n/// Hotel Owner profile — 1-to-1 with users, 1-to-1 with hotels.\n/// user_id IS the primary key: this is a profile, not a separate login.\n/// One user owns exactly one hotel; one hotel has exactly one owner.\nmodel hotel_owners {\n  id       String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id  String  @unique @db.Uuid\n  hotel_id String  @unique @db.Uuid\n  address  String?\n\n  hesabpay_account_number String?   @db.VarChar(30)\n  created_at              DateTime? @default(now()) @db.Timestamptz(6)\n\n  users  users  @relation(fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  hotels hotels @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n}\n\nmodel pending_signups {\n  id                   String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  subscription_plan_id String  @db.Uuid\n  hotel_name           String  @db.VarChar(150)\n  owner_name           String  @db.VarChar(150)\n  email                String  @db.VarChar(150)\n  phone                String? @db.VarChar(30)\n\n  reveal_password   String?   @db.VarChar(64)\n  reveal_expires_at DateTime? @db.Timestamptz(6)\n\n  status String @default(\"pending\") @db.VarChar(20)\n\n  hesabpay_session_id String? @db.VarChar(150)\n  created_hotel_id    String? @db.Uuid\n\n  created_at         DateTime?          @default(now()) @db.Timestamptz(6)\n  paid_at            DateTime?          @db.Timestamptz(6)\n  expires_at         DateTime?          @db.Timestamptz(6)\n  subscription_plans subscription_plans @relation(fields: [subscription_plan_id], references: [id])\n\n  @@index([subscription_plan_id], map: \"idx_pending_signups_plan\")\n  @@index([status], map: \"idx_pending_signups_status\")\n  @@index([expires_at], map: \"idx_pending_signups_expires\")\n}\n\nmodel email_verifications {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  email       String    @db.VarChar(150)\n  otp         String    @db.VarChar(6)\n  attempts    Int       @default(0)\n  expires_at  DateTime  @db.Timestamptz(6)\n  verified_at DateTime? @db.Timestamptz(6)\n  created_at  DateTime? @default(now()) @db.Timestamptz(6)\n\n  @@index([email], map: \"idx_email_verifications_email\")\n}\n\nmodel subscription_plans {\n  id              String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name            String          @db.VarChar(100)\n  max_branches    Int             @default(1)\n  max_pos_devices Int             @default(2)\n  price_monthly   Decimal         @db.Decimal(12, 2)\n  sections        plan_sections[]\n\n  is_active       Boolean?          @default(true)\n  created_at      DateTime?         @default(now()) @db.Timestamptz(6)\n  hotels          hotels[]\n  pending_signups pending_signups[]\n}\n\n/// Master catalogue of every gated feature area (\"section\") in the app.\n/// e.g. key = \"rooms\", \"pos\", \"inventory\", \"kitchen\", \"payroll\", \"reports\" ...\nmodel sections {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  key         String    @unique @db.VarChar(50) // machine name, e.g. \"rooms\"\n  name        String    @db.VarChar(100) // display name, e.g. \"Rooms & Stays\"\n  description String?\n  icon        String?   @db.VarChar(50)\n  sort_order  Int?      @default(0)\n  is_active   Boolean?  @default(true)\n  created_at  DateTime? @default(now()) @db.Timestamptz(6)\n\n  plan_sections plan_sections[]\n\n  @@index([is_active], map: \"idx_sections_active\")\n}\n\n/// Which sections each plan unlocks. Join table.\nmodel plan_sections {\n  plan_id    String  @db.Uuid\n  section_id String  @db.Uuid\n  is_enabled Boolean @default(true)\n\n  /// Per-section limits for this plan, e.g. { \"max_rooms\": 20, \"max_items\": 500 }\n  config Json? @default(\"{}\")\n\n  subscription_plans subscription_plans @relation(fields: [plan_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  sections           sections           @relation(fields: [section_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([plan_id, section_id])\n  @@index([section_id], map: \"idx_plan_sections_section\")\n}\n\n// =========================================================\n// PROVINCES — geographic reference data (platform-wide)\n// =========================================================\n\nmodel provinces {\n  id   String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name String @unique @db.VarChar(100) // \"Kabul\", \"Herat\", \"Balkh\"...\n\n  branches branches[]\n}\n\n/// This table contains check constraints and requires additional setup for migrations.\nmodel branches {\n  id                  String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  hotel_id            String    @db.Uuid\n  province_id         String?   @db.Uuid\n  name                String    @db.VarChar(150)\n  code                String?   @db.VarChar(20)\n  address             String?\n  city                String?   @db.VarChar(100)\n  phone               String?   @db.VarChar(30)\n  latitude            Decimal?  @db.Decimal(10, 7)\n  longitude           Decimal?  @db.Decimal(10, 7)\n  currency            String?   @default(\"AFN\") @db.VarChar(10)\n  timezone            String?   @default(\"Asia/Kabul\") @db.VarChar(50)\n  tax_rate            Decimal?  @default(0) @db.Decimal(5, 2)\n  service_charge_rate Decimal?  @default(0) @db.Decimal(5, 2)\n  status              String?   @default(\"active\") @db.VarChar(20)\n  opening_time        DateTime? @db.Time(6)\n  closing_time        DateTime? @db.Time(6)\n  created_at          DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at          DateTime? @default(now()) @db.Timestamptz(6)\n\n  expenses         expenses[]\n  payroll_runs     payroll_runs[]\n  staff_attendance staff_attendance[]\n\n  hotels hotels @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  provinces provinces? @relation(fields: [province_id], references: [id], onDelete: SetNull, onUpdate: NoAction) // ← NEW\n\n  users                users[]\n  audit_logs           audit_logs[]\n  dining_areas         dining_areas[]\n  dining_tables        dining_tables[]\n  discounts            discounts[]\n  inventory_items      inventory_items[]\n  invoices             invoices[]\n  branch_menu_items    branch_menu_items[]\n  orders               orders[]\n  payment_methods      payment_methods[]\n  pos_devices          pos_devices[]\n  printers             printers[]\n  shifts               shifts[]\n  table_sessions       table_sessions[]\n  staff_leave_requests staff_leave_requests[] @relation(\"branch_leave_requests\")\n\n  room_types room_types[]\n  rooms      rooms[]\n  room_stays room_stays[]\n\n  reviews reviews[]\n\n  @@unique([hotel_id, code])\n  @@index([hotel_id], map: \"idx_branches_hotel\")\n  @@index([province_id], map: \"idx_branches_province\") // ← NEW\n}\n\n// =========================================================\n// AUDIT\n// =========================================================\n\n/// actor_id intentionally has no FK — audit rows must survive user deletion.\nmodel audit_logs {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  hotel_id    String?   @db.Uuid\n  branch_id   String?   @db.Uuid\n  actor_id    String?   @db.Uuid\n  actor_type  String?   @db.VarChar(20)\n  action      String    @db.VarChar(100)\n  entity_type String?   @db.VarChar(50)\n  entity_id   String?   @db.Uuid\n  metadata    Json?     @default(\"{}\")\n  created_at  DateTime? @default(now()) @db.Timestamptz(6)\n  branches    branches? @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  hotels      hotels?   @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([branch_id], map: \"idx_audit_branch\")\n  @@index([hotel_id], map: \"idx_audit_hotel\")\n}\n\n// =========================================================\n// FLOOR / DINING\n// =========================================================\n\n/// Local walk-in customer added by staff at POS. Per-hotel. No login.\n/// Online buyers are stored in `buyers` — they are separate identities.\nmodel customers {\n  id             String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  hotel_id       String    @db.Uuid\n  full_name      String?   @db.VarChar(150)\n  phone          String?   @db.VarChar(30)\n  email          String?   @db.VarChar(150)\n  loyalty_points Int?      @default(0)\n  notes          String?\n  created_at     DateTime? @default(now()) @db.Timestamptz(6)\n\n  hotels hotels @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  orders     orders[]\n  room_stays room_stays[]\n  payments   payments[]\n\n  @@unique([hotel_id, phone])\n}\n\nmodel dining_areas {\n  id            String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id     String          @db.Uuid\n  name          String          @db.VarChar(100)\n  branches      branches        @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  dining_tables dining_tables[]\n}\n\nmodel dining_tables {\n  id             String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id      String           @db.Uuid\n  area_id        String?          @db.Uuid\n  table_number   String           @db.VarChar(20)\n  capacity       Int?             @default(4)\n  status         String?          @default(\"available\") @db.VarChar(20)\n  qr_code_token  String?          @unique @db.VarChar(100)\n  created_at     DateTime?        @default(now()) @db.Timestamptz(6)\n  dining_areas   dining_areas?    @relation(fields: [area_id], references: [id], onUpdate: NoAction)\n  branches       branches         @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  table_sessions table_sessions[]\n\n  @@unique([branch_id, table_number])\n  @@index([branch_id], map: \"idx_tables_branch\")\n}\n\nmodel table_sessions {\n  id            String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  table_id      String        @db.Uuid\n  branch_id     String        @db.Uuid\n  opened_by     String?       @db.Uuid\n  guest_count   Int?          @default(1)\n  status        String?       @default(\"open\") @db.VarChar(20)\n  opened_at     DateTime?     @default(now()) @db.Timestamptz(6)\n  closed_at     DateTime?     @db.Timestamptz(6)\n  orders        orders[]\n  branches      branches      @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  users         users?        @relation(fields: [opened_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  dining_tables dining_tables @relation(fields: [table_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([table_id], map: \"idx_sessions_table\")\n}\n\n// =========================================================\n// MENU\n// =========================================================\n\nmodel menu_categories {\n  id         String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  hotel_id   String   @db.Uuid\n  name       String   @db.VarChar(100)\n  sort_order Int?     @default(0)\n  is_active  Boolean? @default(true)\n\n  default_product_category_id String?             @db.Uuid // ← NEW: auto-tag items\n  default_product_category    product_categories? @relation(\"category_default\", fields: [default_product_category_id], references: [id], onDelete: SetNull, onUpdate: NoAction) // ← NEW\n\n  // ── relations ────────────────────────────────────────────\n  hotels     hotels       @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  menu_items menu_items[]\n\n  // ── indexes ──────────────────────────────────────────────\n  @@unique([hotel_id, name])\n  @@index([hotel_id], map: \"idx_menu_categories_hotel\")\n  @@index([default_product_category_id], map: \"idx_menu_categories_default_product\") // ← NEW\n}\n\nmodel menu_items {\n  id                  String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  hotel_id            String  @db.Uuid\n  category_id         String? @db.Uuid\n  product_category_id String? @db.Uuid // ← NEW: platform-wide tag\n\n  name         String    @db.VarChar(150)\n  description  String?\n  image_url    String?\n  base_price   Decimal   @db.Decimal(12, 2)\n  tax_rate     Decimal?  @default(0) @db.Decimal(5, 2)\n  is_available Boolean?  @default(true)\n  is_online    Boolean   @default(false)\n  is_kitchen   Boolean?  @default(true)\n  prep_station String?   @db.VarChar(50)\n  product_kind String    @default(\"prepared\") @db.VarChar(20) // prepared | packaged | retail | ingredient\n  sort_order   Int?      @default(0)\n  created_at   DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at   DateTime? @default(now()) @db.Timestamptz(6)\n\n  // ── relations ────────────────────────────────────────────\n  hotels           hotels              @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  menu_categories  menu_categories?    @relation(fields: [category_id], references: [id], onUpdate: NoAction)\n  product_category product_categories? @relation(fields: [product_category_id], references: [id], onDelete: SetNull, onUpdate: NoAction) // ← NEW\n\n  menu_item_ingredients     menu_item_ingredients[]\n  menu_item_modifier_groups menu_item_modifier_groups[]\n  order_items               order_items[]\n  reviews                   reviews[]\n  branch_items              branch_menu_items[]\n\n  // ── indexes ──────────────────────────────────────────────\n  @@index([hotel_id], map: \"idx_menu_items_hotel\")\n  @@index([category_id], map: \"idx_menu_items_category\")\n  @@index([product_category_id], map: \"idx_menu_items_product_category\") // ← NEW\n  @@index([hotel_id, is_available, is_online], map: \"idx_menu_items_public\")\n  @@index([product_category_id, is_available, is_online], map: \"idx_menu_items_product_category_public\") // ← NEW (fast browse-by-category)\n}\n\nmodel product_categories {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  key         String    @unique @db.VarChar(50)\n  name        String    @db.VarChar(100)\n  description String?\n  icon        String?   @db.VarChar(50)\n  image_url   String?\n  parent_id   String?   @db.Uuid\n  sort_order  Int?      @default(0)\n  is_active   Boolean?  @default(true)\n  created_at  DateTime? @default(now()) @db.Timestamptz(6)\n\n  parent   product_categories?  @relation(\"cat_tree\", fields: [parent_id], references: [id], onDelete: SetNull)\n  children product_categories[] @relation(\"cat_tree\")\n  items    menu_items[]\n\n  menu_categories menu_categories[] @relation(\"category_default\") // ← ADD THIS\n\n  @@index([parent_id], map: \"idx_product_categories_parent\")\n  @@index([is_active, sort_order], map: \"idx_product_categories_active\")\n}\n\nmodel branch_menu_items {\n  branch_id    String @db.Uuid\n  menu_item_id String @db.Uuid\n\n  price_override Decimal? @db.Decimal(12, 2) // null → use menu_items.base_price\n  is_available   Boolean  @default(true) // sold out at this branch?\n  is_online      Boolean  @default(true) // shown in online menu for this branch?\n  sort_order     Int?     @default(0)\n\n  branches  branches   @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  menu_item menu_items @relation(fields: [menu_item_id], references: [id], onDelete: Cascade)\n\n  @@id([branch_id, menu_item_id])\n  @@index([menu_item_id], map: \"idx_bmi_item\")\n  @@index([branch_id, is_online], map: \"idx_bmi_branch_online\")\n}\n\nmodel menu_item_modifier_groups {\n  id                  String                @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  menu_item_id        String                @db.Uuid\n  name                String                @db.VarChar(100)\n  is_required         Boolean?              @default(false)\n  max_selectable      Int?                  @default(1)\n  menu_items          menu_items            @relation(fields: [menu_item_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  menu_item_modifiers menu_item_modifiers[]\n}\n\nmodel menu_item_modifiers {\n  id                        String                    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  group_id                  String                    @db.Uuid\n  name                      String                    @db.VarChar(100)\n  extra_price               Decimal?                  @default(0) @db.Decimal(12, 2)\n  menu_item_modifier_groups menu_item_modifier_groups @relation(fields: [group_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n}\n\n// =========================================================\n// INVENTORY\n// =========================================================\n\nmodel inventory_items {\n  id                     String                   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id              String                   @db.Uuid\n  name                   String                   @db.VarChar(150)\n  unit                   String?                  @db.VarChar(20)\n  quantity_on_hand       Decimal?                 @default(0) @db.Decimal(12, 3)\n  reorder_level          Decimal?                 @default(0) @db.Decimal(12, 3)\n  updated_at             DateTime?                @default(now()) @db.Timestamptz(6)\n  branches               branches                 @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  inventory_transactions inventory_transactions[]\n  menu_item_ingredients  menu_item_ingredients[]\n}\n\nmodel menu_item_ingredients {\n  menu_item_id      String          @db.Uuid\n  inventory_item_id String          @db.Uuid\n  quantity_required Decimal         @db.Decimal(12, 3)\n  inventory_items   inventory_items @relation(fields: [inventory_item_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  menu_items        menu_items      @relation(fields: [menu_item_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([menu_item_id, inventory_item_id])\n}\n\nmodel inventory_transactions {\n  id                 String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  inventory_item_id  String          @db.Uuid\n  change_type        String?         @db.VarChar(20)\n  quantity_change    Decimal         @db.Decimal(12, 3)\n  reference_order_id String?         @db.Uuid\n  created_by         String?         @db.Uuid\n  created_at         DateTime?       @default(now()) @db.Timestamptz(6)\n  users              users?          @relation(fields: [created_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  inventory_items    inventory_items @relation(fields: [inventory_item_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  orders             orders?         @relation(fields: [reference_order_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n}\n\n// =========================================================\n// ORDERS / KITCHEN\n// =========================================================\n\n/// An order is EITHER a POS order (customer_id set, buyer_id null)\n/// OR an online order (buyer_id set, customer_id null). Never both.\nmodel orders {\n  id                     String                   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id              String                   @db.Uuid\n  table_session_id       String?                  @db.Uuid\n  customer_id            String?                  @db.Uuid\n  buyer_id               String?                  @db.Uuid\n  room_stay_id           String?                  @db.Uuid\n  order_number           String                   @db.VarChar(30)\n  order_type             String                   @default(\"dine_in\") @db.VarChar(20)\n  status                 String                   @default(\"open\") @db.VarChar(20)\n  waiter_id              String?                  @db.Uuid\n  subtotal               Decimal                  @default(0) @db.Decimal(12, 2)\n  discount_amount        Decimal                  @default(0) @db.Decimal(12, 2)\n  tax_amount             Decimal                  @default(0) @db.Decimal(12, 2)\n  service_charge         Decimal                  @default(0) @db.Decimal(12, 2)\n  total_amount           Decimal                  @default(0) @db.Decimal(12, 2)\n  notes                  String?\n  source                 String?                  @default(\"pos\") @db.VarChar(20) // pos | customer | qr\n  public_token           String?                  @unique @db.VarChar(64)\n  created_at             DateTime?                @default(now()) @db.Timestamptz(6)\n  updated_at             DateTime?                @default(now()) @db.Timestamptz(6)\n  payment_status         String?                  @default(\"unpaid\") @db.VarChar(20) // unpaid | paid | failed | refunded\n  payment_reference      String?                  @db.VarChar(150) // HesabPay session/transaction id\n  paid_at                DateTime?                @db.Timestamptz(6)\n  online_details         online_order_details?\n  payout                 order_payouts?\n  inventory_transactions inventory_transactions[]\n  invoices               invoices[]\n  kitchen_tickets        kitchen_tickets[]\n  order_discounts        order_discounts[]\n  order_items            order_items[]\n  reviews                reviews[]\n\n  branches       branches        @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  customers      customers?      @relation(fields: [customer_id], references: [id], onUpdate: NoAction)\n  buyers         buyers?         @relation(fields: [buyer_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  table_sessions table_sessions? @relation(fields: [table_session_id], references: [id], onUpdate: NoAction)\n  room_stays     room_stays?     @relation(fields: [room_stay_id], references: [id], onUpdate: NoAction)\n  users          users?          @relation(fields: [waiter_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  payments       payments[]\n\n  @@unique([branch_id, order_number])\n  @@index([branch_id], map: \"idx_orders_branch\")\n  @@index([table_session_id], map: \"idx_orders_session\")\n  @@index([room_stay_id], map: \"idx_orders_room_stay\")\n  @@index([status], map: \"idx_orders_status\")\n  @@index([source], map: \"idx_orders_source\")\n  @@index([buyer_id], map: \"idx_orders_buyer\")\n}\n\nmodel online_order_details {\n  id       String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id String @unique @db.Uuid\n\n  // ── contact (required for every online order) ──\n  contact_name  String @db.VarChar(150)\n  contact_phone String @db.VarChar(30)\n\n  // ── delivery (null for pickup) ──\n  delivery_address String?\n  delivery_city    String?  @db.VarChar(100)\n  delivery_lat     Decimal? @db.Decimal(10, 7)\n  delivery_lng     Decimal? @db.Decimal(10, 7)\n  delivery_notes   String?\n\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n  updated_at DateTime @default(now()) @db.Timestamptz(6)\n\n  orders orders @relation(fields: [order_id], references: [id], onDelete: Cascade)\n\n  @@index([order_id], map: \"idx_online_details_order\")\n}\n\nmodel platform_settings {\n  id                 String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  commission_rate    Decimal  @default(5.00) @db.Decimal(5, 2) // %\n  commission_account String?  @db.VarChar(30) // where the 5% goes (optional — see note below)\n  updated_at         DateTime @default(now()) @db.Timestamptz(6)\n}\n\n// Payout ledger — one row per order payment distribution\nmodel order_payouts {\n  id                 String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id           String    @unique @db.Uuid\n  hotel_id           String    @db.Uuid\n  owner_account      String    @db.VarChar(30)\n  commission_account String?   @db.VarChar(30)\n  gross_amount       Decimal   @db.Decimal(12, 2)\n  platform_fee       Decimal   @db.Decimal(12, 2)\n  owner_amount       Decimal   @db.Decimal(12, 2)\n  status             String    @default(\"pending\") @db.VarChar(20) // pending | completed | failed\n  transaction_id     String?   @db.VarChar(150)\n  error_message      String?\n  created_at         DateTime  @default(now()) @db.Timestamptz(6)\n  completed_at       DateTime? @db.Timestamptz(6)\n\n  orders orders @relation(fields: [order_id], references: [id], onDelete: Cascade)\n\n  @@index([hotel_id])\n  @@index([status])\n}\n\nmodel order_items {\n  id                   String                 @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id             String                 @db.Uuid\n  menu_item_id         String                 @db.Uuid\n  quantity             Int                    @default(1)\n  unit_price           Decimal                @db.Decimal(12, 2)\n  modifiers            Json?                  @default(\"[]\")\n  line_total           Decimal                @db.Decimal(12, 2)\n  notes                String?\n  status               String?                @default(\"pending\") @db.VarChar(20)\n  created_at           DateTime?              @default(now()) @db.Timestamptz(6)\n  kitchen_ticket_items kitchen_ticket_items[]\n  menu_items           menu_items             @relation(fields: [menu_item_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  orders               orders                 @relation(fields: [order_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([order_id], map: \"idx_order_items_order\")\n  @@index([menu_item_id], map: \"idx_order_items_menu_item\")\n}\n\nmodel kitchen_ticket_items {\n  kitchen_ticket_id String          @db.Uuid\n  order_item_id     String          @db.Uuid\n  kitchen_tickets   kitchen_tickets @relation(fields: [kitchen_ticket_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  order_items       order_items     @relation(fields: [order_item_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([kitchen_ticket_id, order_item_id])\n}\n\nmodel kitchen_tickets {\n  id                   String                 @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id             String                 @db.Uuid\n  prep_station         String?                @db.VarChar(50)\n  printed_at           DateTime?              @db.Timestamptz(6)\n  status               String?                @default(\"queued\") @db.VarChar(20)\n  created_at           DateTime?              @default(now()) @db.Timestamptz(6)\n  kitchen_ticket_items kitchen_ticket_items[]\n  orders               orders                 @relation(fields: [order_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n}\n\n// =========================================================\n// REVIEWS — only online buyers can review\n// =========================================================\n\n/// A review is always written by a logged-in buyer (self-signup,\n/// platform-wide). POS walk-in customers CANNOT review — no\n/// `customer_id` field on purpose. `order_id` links the review\n/// back to the specific order the buyer placed.\nmodel reviews {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  menu_item_id String    @db.Uuid\n  branch_id    String    @db.Uuid\n  order_id     String?   @db.Uuid\n  buyer_id     String    @db.Uuid\n  rating       Int // 1..5\n  comment      String?\n  created_at   DateTime? @default(now()) @db.Timestamptz(6)\n\n  menu_items menu_items @relation(fields: [menu_item_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  branches   branches   @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  orders     orders?    @relation(fields: [order_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  buyers     buyers     @relation(fields: [buyer_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([menu_item_id], map: \"idx_reviews_item\")\n  @@index([branch_id], map: \"idx_reviews_branch\")\n  @@index([buyer_id], map: \"idx_reviews_buyer\")\n  @@index([rating], map: \"idx_reviews_rating\")\n}\n\n// =========================================================\n// DISCOUNTS / PAYMENTS / INVOICES\n// =========================================================\n\nmodel discounts {\n  id                String            @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id         String            @db.Uuid\n  name              String?           @db.VarChar(100)\n  type              String?           @db.VarChar(10)\n  value             Decimal           @db.Decimal(12, 2)\n  requires_approval Boolean?          @default(false)\n  is_active         Boolean?          @default(true)\n  branches          branches          @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  order_discounts   order_discounts[]\n}\n\nmodel order_discounts {\n  order_id       String    @db.Uuid\n  discount_id    String    @db.Uuid\n  applied_by     String?   @db.Uuid\n  amount_applied Decimal   @db.Decimal(12, 2)\n  users          users?    @relation(fields: [applied_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  discounts      discounts @relation(fields: [discount_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  orders         orders    @relation(fields: [order_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@id([order_id, discount_id])\n}\n\nmodel payment_methods {\n  id              String     @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id       String     @db.Uuid\n  name            String     @db.VarChar(50)\n  type            String     @db.VarChar(20)\n  provider_config Json?      @default(\"{}\")\n  is_active       Boolean?   @default(true)\n  branches        branches   @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  payments        payments[]\n  expenses        expenses[]\n}\n\nmodel payments {\n  id                String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id          String?   @db.Uuid\n  room_stay_id      String?   @db.Uuid\n  customer_id       String?   @db.Uuid\n  buyer_id          String?   @db.Uuid\n  payment_method_id String    @db.Uuid\n  amount            Decimal   @db.Decimal(12, 2)\n  amount_tendered   Decimal?  @db.Decimal(12, 2)\n  change_given      Decimal?  @default(0) @db.Decimal(12, 2)\n  status            String?   @default(\"completed\") @db.VarChar(20)\n  transaction_ref   String?   @db.VarChar(150)\n  received_by       String?   @db.Uuid\n  paid_at           DateTime? @default(now()) @db.Timestamptz(6)\n  notes             String?\n\n  orders          orders?         @relation(fields: [order_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  room_stays      room_stays?     @relation(fields: [room_stay_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  customers       customers?      @relation(fields: [customer_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  buyers          buyers?         @relation(fields: [buyer_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  payment_methods payment_methods @relation(fields: [payment_method_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  users           users?          @relation(fields: [received_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  @@index([order_id], map: \"idx_payments_order\")\n  @@index([room_stay_id], map: \"idx_payments_room_stay\")\n  @@index([customer_id], map: \"idx_payments_customer\")\n  @@index([buyer_id], map: \"idx_payments_buyer\")\n}\n\nmodel invoices {\n  id              String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  order_id        String    @db.Uuid\n  branch_id       String    @db.Uuid\n  invoice_number  String    @db.VarChar(30)\n  subtotal        Decimal   @db.Decimal(12, 2)\n  discount_amount Decimal   @default(0) @db.Decimal(12, 2)\n  tax_amount      Decimal   @default(0) @db.Decimal(12, 2)\n  service_charge  Decimal   @default(0) @db.Decimal(12, 2)\n  total_amount    Decimal   @db.Decimal(12, 2)\n  printed_count   Int?      @default(0)\n  pdf_url         String?\n  created_at      DateTime? @default(now()) @db.Timestamptz(6)\n  branches        branches  @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  orders          orders    @relation(fields: [order_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([branch_id, invoice_number])\n}\n\n// =========================================================\n// DEVICES / SHIFTS\n// =========================================================\n\nmodel pos_devices {\n  id                String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id         String    @db.Uuid\n  device_name       String?   @db.VarChar(100)\n  device_uid        String?   @unique @db.VarChar(150)\n  device_type       String?   @default(\"mobile_pos\") @db.VarChar(20)\n  assigned_staff_id String?   @db.Uuid\n  last_seen_at      DateTime? @db.Timestamptz(6)\n  is_active         Boolean?  @default(true)\n  created_at        DateTime? @default(now()) @db.Timestamptz(6)\n  users             users?    @relation(fields: [assigned_staff_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  branches          branches  @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n}\n\nmodel printers {\n  id                 String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id          String   @db.Uuid\n  name               String?  @db.VarChar(100)\n  printer_type       String?  @default(\"receipt\") @db.VarChar(20)\n  connection_type    String?  @default(\"bluetooth\") @db.VarChar(20)\n  connection_address String?  @db.VarChar(150)\n  prep_station       String?  @db.VarChar(50)\n  is_active          Boolean? @default(true)\n  branches           branches @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n}\n\nmodel shifts {\n  id            String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id     String    @db.Uuid\n  staff_id      String    @db.Uuid\n  opening_cash  Decimal?  @default(0) @db.Decimal(12, 2)\n  closing_cash  Decimal?  @default(0) @db.Decimal(12, 2)\n  expected_cash Decimal?  @default(0) @db.Decimal(12, 2)\n  variance      Decimal?  @default(0) @db.Decimal(12, 2)\n  started_at    DateTime? @default(now()) @db.Timestamptz(6)\n  ended_at      DateTime? @db.Timestamptz(6)\n  status        String?   @default(\"open\") @db.VarChar(20)\n  branches      branches  @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  users         users     @relation(fields: [staff_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n}\n\n// =========================================================\n// LEAVE REQUESTS\n// =========================================================\n\nmodel staff_leave_requests {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id     String    @db.Uuid\n  branch_id   String    @db.Uuid\n  leave_type  String    @db.VarChar(30)\n  start_date  DateTime  @db.Date\n  end_date    DateTime  @db.Date\n  reason      String?\n  status      String    @default(\"pending\") @db.VarChar(20)\n  approved_by String?   @db.Uuid\n  approved_at DateTime? @db.Timestamptz(6)\n  created_at  DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at  DateTime? @default(now()) @db.Timestamptz(6)\n\n  user     users    @relation(\"leave_requester\", fields: [user_id], references: [id], onDelete: Cascade)\n  branch   branches @relation(\"branch_leave_requests\", fields: [branch_id], references: [id], onDelete: Cascade)\n  approver users?   @relation(\"leave_approver\", fields: [approved_by], references: [id])\n\n  @@index([user_id])\n  @@index([branch_id])\n  @@index([status])\n}\n\n// =========================================================\n// EXPENSES\n// =========================================================\n\n/// Category bucket for expenses (Rent, Utilities, Maintenance, Supplies...)\n/// Scoped at hotel level so all branches of a hotel share the same categories.\nmodel expense_categories {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  hotel_id    String   @db.Uuid\n  name        String   @db.VarChar(100)\n  description String?\n  is_active   Boolean? @default(true)\n\n  hotels   hotels     @relation(fields: [hotel_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  expenses expenses[]\n\n  @@unique([hotel_id, name])\n}\n\n/// Day-to-day operating expenses for a branch (rent, utilities, repairs,\n/// supplier purchases that aren't inventory, etc). Distinct from\n/// staff payroll, which lives in payslips below.\nmodel expenses {\n  id                String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id         String  @db.Uuid\n  category_id       String? @db.Uuid\n  payment_method_id String? @db.Uuid\n\n  title       String  @db.VarChar(150)\n  description String?\n  amount      Decimal @db.Decimal(12, 2)\n  vendor_name String? @db.VarChar(150)\n  receipt_url String?\n\n  expense_date DateTime @default(now()) @db.Date\n  status       String?  @default(\"pending\") @db.VarChar(20) // pending | approved | rejected | paid\n\n  is_recurring        Boolean? @default(false)\n  recurrence_interval String?  @db.VarChar(20)\n\n  created_by  String?   @db.Uuid\n  approved_by String?   @db.Uuid\n  approved_at DateTime? @db.Timestamptz(6)\n\n  created_at DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at DateTime? @default(now()) @db.Timestamptz(6)\n\n  branches           branches            @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  expense_categories expense_categories? @relation(fields: [category_id], references: [id], onUpdate: NoAction)\n  payment_methods    payment_methods?    @relation(fields: [payment_method_id], references: [id], onUpdate: NoAction)\n\n  creator  users? @relation(\"expense_creator\", fields: [created_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  approver users? @relation(\"expense_approver\", fields: [approved_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  @@index([branch_id], map: \"idx_expenses_branch\")\n  @@index([category_id], map: \"idx_expenses_category\")\n  @@index([status], map: \"idx_expenses_status\")\n  @@index([expense_date], map: \"idx_expenses_date\")\n}\n\n// =========================================================\n// HR / PAYROLL\n// =========================================================\n\n/// Current + historical salary structure per staff member.\n/// Keep old rows (is_current = false) instead of overwriting, so payroll\n/// history stays accurate even after a raise.\nmodel staff_salaries {\n  id             String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id        String    @db.Uuid\n  salary_type    String    @default(\"monthly\") @db.VarChar(20) // monthly | hourly | daily\n  base_amount    Decimal   @db.Decimal(12, 2)\n  bonus_amount   Decimal?  @default(0) @db.Decimal(12, 2)\n  currency       String?   @default(\"AFN\") @db.VarChar(10)\n  effective_from DateTime  @db.Date\n  effective_to   DateTime? @db.Date\n  is_current     Boolean?  @default(true)\n  created_at     DateTime? @default(now()) @db.Timestamptz(6)\n\n  users users @relation(fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([user_id], map: \"idx_staff_salaries_user\")\n}\n\n/// One payroll batch per branch per pay period (e.g. \"August 2026\").\nmodel payroll_runs {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id    String    @db.Uuid\n  period_start DateTime  @db.Date\n  period_end   DateTime  @db.Date\n  status       String?   @default(\"draft\") @db.VarChar(20) // draft | processed | paid\n  processed_by String?   @db.Uuid\n  processed_at DateTime? @db.Timestamptz(6)\n  created_at   DateTime? @default(now()) @db.Timestamptz(6)\n\n  branches  branches   @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  processor users?     @relation(\"payroll_processor\", fields: [processed_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  payslips  payslips[]\n\n  @@unique([branch_id, period_start, period_end])\n  @@index([branch_id], map: \"idx_payroll_runs_branch\")\n}\n\n/// One line per staff member within a payroll run — the actual amount paid.\nmodel payslips {\n  id             String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  payroll_run_id String @db.Uuid\n  user_id        String @db.Uuid\n\n  base_salary      Decimal  @db.Decimal(12, 2)\n  bonus_amount     Decimal? @default(0) @db.Decimal(12, 2)\n  deduction_amount Decimal? @default(0) @db.Decimal(12, 2)\n  advance_deducted Decimal? @default(0) @db.Decimal(12, 2)\n  net_pay          Decimal  @db.Decimal(12, 2)\n\n  status  String?   @default(\"unpaid\") @db.VarChar(20) // unpaid | paid\n  paid_at DateTime? @db.Timestamptz(6)\n  notes   String?\n\n  payroll_runs payroll_runs @relation(fields: [payroll_run_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  users        users        @relation(\"payslip_recipient\", fields: [user_id], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  @@unique([payroll_run_id, user_id])\n  @@index([user_id], map: \"idx_payslips_user\")\n}\n\n/// Salary advances / loans given to staff, later deducted from a payslip.\nmodel staff_advances {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id      String    @db.Uuid\n  amount       Decimal   @db.Decimal(12, 2)\n  reason       String?\n  status       String?   @default(\"pending\") @db.VarChar(20) // pending | approved | repaid | rejected\n  requested_at DateTime? @default(now()) @db.Timestamptz(6)\n  approved_by  String?   @db.Uuid\n\n  recipient users  @relation(\"advance_recipient\", fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  approver  users? @relation(\"advance_approver\", fields: [approved_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  @@index([user_id], map: \"idx_advances_user\")\n}\n\nmodel tutorials {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  language    String    @db.VarChar(10)\n  category    String    @db.VarChar(100)\n  title       String    @db.VarChar(200)\n  description String?\n  youtube_id  String    @db.VarChar(50)\n  duration    String?   @db.VarChar(20)\n  sort_order  Int?      @default(0)\n  is_active   Boolean?  @default(true)\n  created_at  DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at  DateTime? @default(now()) @db.Timestamptz(6)\n\n  @@index([language], map: \"idx_tutorials_language\")\n  @@index([is_active], map: \"idx_tutorials_active\")\n}\n\n/// Clock-in/out records used to compute payroll deductions.\nmodel staff_attendance {\n  id        String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id   String    @db.Uuid\n  branch_id String    @db.Uuid\n  check_in  DateTime  @db.Timestamptz(6)\n  check_out DateTime? @db.Timestamptz(6)\n  status    String?   @default(\"present\") @db.VarChar(20) // present | absent | late | leave\n  notes     String?\n\n  users    users    @relation(fields: [user_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  branches branches @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([user_id], map: \"idx_attendance_user\")\n  @@index([branch_id], map: \"idx_attendance_branch\")\n}\n\n// =========================================================\n// ROOMS — walk-in assignment, rent + running orders\n// =========================================================\n\n/// Physical room types configured per branch (Double, VIP, Single...).\nmodel room_types {\n  id         String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id  String   @db.Uuid\n  name       String   @db.VarChar(100)\n  base_price Decimal  @db.Decimal(12, 2)\n  capacity   Int      @default(2)\n  is_active  Boolean? @default(true)\n\n  branches branches @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  rooms    rooms[]\n\n  @@index([branch_id], map: \"idx_room_types_branch\")\n}\n\n/// One row per physical room in a branch.\n/// status: available | occupied | cleaning | maintenance\nmodel rooms {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id    String    @db.Uuid\n  room_type_id String    @db.Uuid\n  room_number  String    @db.VarChar(20)\n  floor        String?   @db.VarChar(20)\n  status       String    @default(\"available\") @db.VarChar(20)\n  notes        String?\n  is_active    Boolean?  @default(true)\n  created_at   DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at   DateTime? @default(now()) @db.Timestamptz(6)\n\n  branches   branches     @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  room_types room_types   @relation(fields: [room_type_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  room_stays room_stays[]\n\n  @@unique([branch_id, room_number])\n  @@index([branch_id], map: \"idx_rooms_branch\")\n  @@index([status], map: \"idx_rooms_status\")\n}\n\n/// A running stay for one room. Can be assigned to a POS customer\n/// (staff-checked-in walk-in) OR to an online buyer (self-booked).\n/// Exactly one of customer_id / buyer_id is set.\nmodel room_stays {\n  id        String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  branch_id String @db.Uuid\n  room_id   String @db.Uuid\n\n  customer_id String? @db.Uuid\n  buyer_id    String? @db.Uuid\n  guest_name  String? @db.VarChar(150)\n  guest_phone String? @db.VarChar(30)\n  guest_id_no String? @db.VarChar(60)\n\n  check_in_at        DateTime  @default(now()) @db.Timestamptz(6)\n  expected_check_out DateTime? @db.Date\n  actual_check_out   DateTime? @db.Timestamptz(6)\n\n  rate_per_night Decimal @db.Decimal(12, 2)\n  nights         Int     @default(1)\n  rent_total     Decimal @default(0) @db.Decimal(12, 2)\n  orders_total   Decimal @default(0) @db.Decimal(12, 2)\n  grand_total    Decimal @default(0) @db.Decimal(12, 2)\n  paid_amount    Decimal @default(0) @db.Decimal(12, 2)\n\n  status  String  @default(\"active\") @db.VarChar(20)\n  is_paid Boolean @default(false)\n\n  checked_in_by  String? @db.Uuid\n  checked_out_by String? @db.Uuid\n  notes          String?\n\n  created_at DateTime? @default(now()) @db.Timestamptz(6)\n  updated_at DateTime? @default(now()) @db.Timestamptz(6)\n\n  branches    branches   @relation(fields: [branch_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  rooms       rooms      @relation(fields: [room_id], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  customers   customers? @relation(fields: [customer_id], references: [id], onUpdate: NoAction)\n  buyers      buyers?    @relation(fields: [buyer_id], references: [id], onDelete: SetNull, onUpdate: NoAction)\n  checked_in  users?     @relation(\"stay_checkin\", fields: [checked_in_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  checked_out users?     @relation(\"stay_checkout\", fields: [checked_out_by], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  orders   orders[]\n  payments payments[]\n\n  @@index([branch_id], map: \"idx_stays_branch\")\n  @@index([room_id], map: \"idx_stays_room\")\n  @@index([status], map: \"idx_stays_status\")\n  @@index([buyer_id], map: \"idx_stays_buyer\")\n}\n"
}

